from qgis.PyQt.QtWidgets import QAction, QToolBar
mw = iface.mainWindow()
hits = []
for x in mw.findChildren(QAction):
    blob = (x.objectName() or '') + '|' + (x.text() or '')
    if 'reset' in blob.lower():
        hits.append({'text': x.text(), 'objectName': x.objectName(), 'enabled': x.isEnabled(),
                     'checkable': x.isCheckable(), 'visible': x.isVisible(), 'tooltip': x.toolTip()})
tb = None
for t in mw.findChildren(QToolBar):
    if t.objectName() == 'mGpsToolBar':
        tb = t
        break
for h in hits:
    for x in mw.findChildren(QAction):
        if x.objectName() == h['objectName'] and h['objectName']:
            w = tb.widgetForAction(x)
            h['in_gps_toolbar'] = w is not None
            h['button_enabled'] = w.isEnabled() if w else None
result = hits
